def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    frame = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    r0 = min(r for r, c in frame)
    r1 = max(r for r, c in frame)
    c0 = min(c for r, c in frame)
    c1 = max(c for r, c in frame)

    mid_r = (r0 + r1) / 2
    mid_c = (c0 + c1) / 2
    diagonal_colors = {}

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not (r0 <= r <= r1 and c0 <= c <= c1):
                continue
            if grid[r][c] != 0:
                continue
            # Only fill the empty interior of the frame.
            if not (r0 < r < r1 and c0 < c < c1):
                continue

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 and (r < r0 or r > r1 or c < c0 or c > c1):
                top = r < mid_r
                left = c < mid_c
                diagonal_colors[(top == left)] = color

    # Find the colored markers outside the frame and associate each with a diagonal.
    diagonal_colors = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r0 <= r <= r1 and c0 <= c <= c1):
                continue
            top = r < mid_r
            left = c < mid_c
            diagonal_colors[top == left] = color

    rm = (r0 + r1) // 2
    cm = (c0 + c1) // 2
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            top = r <= rm
            left = c <= cm
            key = top == left
            if key in diagonal_colors:
                out[r][c] = diagonal_colors[key]

    return out
